body.page-donate-alumni .plan-card {
  position: relative;
  min-height: 218px;
  background: linear-gradient(180deg, var(--surface-2), var(--surface));
  border: 2px solid var(--border);
  border-radius: var(--radius);
  padding: 22px 22px 20px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  text-align: right;
  transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease, background .18s ease;
}

body.page-donate-alumni .plan-card:hover,
body.page-donate-alumni .plan-card:focus-visible {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  outline: none;
}

body.page-donate-alumni .plan-card::after {
  content: "";
  position: absolute;
  inset: auto -50px -70px auto;
  width: 150px;
  height: 150px;
  border-radius: 50%;
  opacity: .12;
  background: currentColor;
  transition: transform .18s ease, opacity .18s ease;
}

body.page-donate-alumni .plan-card:hover::after {
  transform: scale(1.15);
  opacity: .18;
}

body.page-donate-alumni .plan-dot {
  position: absolute;
  top: 18px;
  left: 18px;
  width: 23px;
  height: 23px;
  border: 2px solid #dbe3ef;
  border-radius: 50%;
  background: white;
  transition: border-color .18s ease, box-shadow .18s ease, background .18s ease;
}

body.page-donate-alumni .plan-card:hover .plan-dot,
body.page-donate-alumni .plan-card:focus-visible .plan-dot {
  border-color: currentColor;
  box-shadow: 0 0 0 5px color-mix(in srgb, currentColor 14%, transparent);
}

body.page-donate-alumni .plan-dot::after {
  content: "";
  position: absolute;
  inset: 5px;
  border-radius: 50%;
  background: currentColor;
  transform: scale(0);
  transition: transform .18s ease;
}

body.page-donate-alumni .plan-card:hover .plan-dot::after,
body.page-donate-alumni .plan-card:focus-visible .plan-dot::after {
  transform: scale(1);
}

