/* Opening logo animation */

body.page-donate-main .opening-splash {
  position: fixed;
  inset: 0;
  z-index: 999999;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, rgba(7,21,34,.78) 0%, rgba(14,58,95,.72) 52%, rgba(7,21,34,.84) 100%),
    url(data:image/png;base64,) center / cover no-repeat;
  overflow: hidden;
  animation: splashFadeOut .75s ease 2.65s forwards;
}

body.page-donate-main .opening-splash::before {
  content: "";
  position: absolute;
  width: 140vmax;
  height: 140vmax;
  background: conic-gradient(from 180deg, transparent 0deg, rgba(255,255,255,.14) 42deg, transparent 85deg, transparent 360deg);
  animation: splashLightSweep 2.6s ease-in-out forwards;
  opacity: .55;
}

body.page-donate-main .opening-splash::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 50%, transparent 0 22%, rgba(0,0,0,.28) 72%),
    linear-gradient(to bottom, rgba(255,255,255,.08), transparent 38%, rgba(0,0,0,.2));
  pointer-events: none;
}

body.page-donate-main .opening-splash__card {
  position: relative;
  z-index: 2;
  width: min(82vw, 520px);
  aspect-ratio: 1.35 / 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border-radius: 0;
  background: transparent;
  border: 0;
  box-shadow: none;
  transform: translateY(18px) scale(.88);
  opacity: 0;
  animation: splashLogoIn .9s cubic-bezier(.2,.9,.2,1.15) .12s forwards,
             splashLogoFloat 1.8s ease-in-out 1.02s infinite alternate;
}

body.page-donate-main .opening-splash__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter: drop-shadow(0 18px 20px rgba(0,0,0,.38));
}

body.page-donate-main .opening-splash__shine {
  position: absolute;
  inset: -25%;
  background: linear-gradient(115deg, transparent 35%, rgba(255,255,255,.36) 48%, transparent 61%);
  transform: translateX(-95%) rotate(8deg);
  animation: splashShine 1.55s ease .72s forwards;
  pointer-events: none;
}

@keyframes splashLogoIn {
  0% { opacity: 0; transform: translateY(24px) scale(.82); filter: blur(8px); }
    70% { opacity: 1; transform: translateY(0) scale(1.035); filter: blur(0); }
    100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
}

@keyframes splashLogoFloat {
  from { transform: translateY(0) scale(1); }
    to { transform: translateY(-6px) scale(1.012); }
}

@keyframes splashShine {
  from { transform: translateX(-95%) rotate(8deg); }
    to { transform: translateX(95%) rotate(8deg); }
}

@keyframes splashLightSweep {
  from { transform: rotate(0deg) scale(.75); }
    to { transform: rotate(130deg) scale(1); }
}

@keyframes splashFadeOut {
  to { opacity: 0; visibility: hidden; pointer-events: none; }
}

@media (prefers-reduced-motion: reduce) {
  body.page-donate-main .opening-splash,
  body.page-donate-main .opening-splash::before,
  body.page-donate-main .opening-splash__card,
  body.page-donate-main .opening-splash__shine {
    animation: none !important;
  }

  body.page-donate-main .opening-splash {
    display: none;
  }
}

